CREATE TABLE IF NOT EXISTS lead_attribution (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid NOT NULL, user_id text NOT NULL, email text DEFAULT '', fb_lead_id text DEFAULT '', fbclid text DEFAULT '', fbc text DEFAULT '', fbp text DEFAULT '', campaign_id text DEFAULT '', campaign_name text DEFAULT '', adset_id text DEFAULT '', adset_name text DEFAULT '', ad_id text DEFAULT '', ad_name text DEFAULT '', form_id text DEFAULT '', utm_source text DEFAULT '', utm_medium text DEFAULT '', utm_campaign text DEFAULT '', utm_content text DEFAULT '', utm_term text DEFAULT '', landing_page_url text DEFAULT '', first_touch_at timestamptz DEFAULT now(), last_touch_at timestamptz DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now())